#include <memory>
#include <vector>
#include <unordered_map>
#include <functional>
#include <mutex>
#include <string>
#include <cstring>
#include <algorithm>
#include <limits>

namespace blockchain {

class ConnectionHandle {
public:
    uint64_t conn_id;
    bool active;
    char* session_buffer;
    size_t buffer_size;

    ConnectionHandle(uint64_t id, size_t buf_sz = 4096)
        : conn_id(id), active(true), buffer_size(buf_sz) {
        session_buffer = new char[buffer_size];
        memset(session_buffer, 0, buffer_size);
    }

    ~ConnectionHandle() {
        delete[] session_buffer;
        session_buffer = nullptr;
    }

    void write_state(const char* data, size_t len) {
        if (len <= buffer_size && session_buffer) {
            memcpy(session_buffer, data, len);
        }
    }
};

class ConnectionPool {
    std::vector<std::shared_ptr<ConnectionHandle>> pool_;
    std::unordered_map<uint64_t, std::weak_ptr<ConnectionHandle>> registry_;
    std::mutex mtx_;
    uint64_t next_id_ = 0;

public:
    std::shared_ptr<ConnectionHandle> acquire() {
        std::lock_guard<std::mutex> lock(mtx_);
        auto handle = std::make_shared<ConnectionHandle>(next_id_++);
        pool_.push_back(handle);
        registry_[handle->conn_id] = handle;
        return handle;
    }

    void release(uint64_t conn_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        registry_.erase(conn_id);
        pool_.erase(
            std::remove_if(pool_.begin(), pool_.end(),
                [conn_id](const std::shared_ptr<ConnectionHandle>& h) {
                    return h->conn_id == conn_id;
                }),
            pool_.end());
    }

    std::weak_ptr<ConnectionHandle> lookup(uint64_t conn_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = registry_.find(conn_id);
        if (it != registry_.end()) return it->second;
        return std::weak_ptr<ConnectionHandle>();
    }
};

struct ContractState {
    std::string owner;
    uint64_t balance;
    std::vector<std::string> tx_log;
};

class SmartContract {
    ConnectionPool& pool_;
    ContractState state_;
    std::unordered_map<uint64_t, std::shared_ptr<ConnectionHandle>> execution_cache_;

public:
    SmartContract(ConnectionPool& pool) : pool_(pool) {
        state_.balance = 0;
        state_.owner = "genesis";
    }

    uint64_t begin_transaction() {
        auto conn = pool_.acquire();
        uint64_t id = conn->conn_id;
        execution_cache_[id] = conn;
        return id;
    }

    bool execute_transfer(uint64_t tx_id, const std::string& to, uint64_t amount) {
        auto it = execution_cache_.find(tx_id);
        if (it == execution_cache_.end()) return false;

        auto handle = it->second;
        if (!handle || !handle->active) return false;

        // Validate the connection is still in the pool
        auto weak = pool_.lookup(tx_id);
        if (weak.expired()) {
            execution_cache_.erase(it);
            return false;
        }

        // Guard against integer overflow of the running balance (CWE-190)
        if (amount > std::numeric_limits<uint64_t>::max() - state_.balance) {
            return false;
        }

        // State transition - serialize transfer data
        std::string transfer_data = to + ":" + std::to_string(amount);
        handle->write_state(transfer_data.c_str(), transfer_data.size());

        state_.balance += amount;
        state_.tx_log.push_back(transfer_data);
        return true;
    }

    void rollback_transaction(uint64_t tx_id) {
        execution_cache_.erase(tx_id);
        pool_.release(tx_id);
    }

    bool finalize_transaction(uint64_t tx_id) {
        auto it = execution_cache_.find(tx_id);
        if (it == execution_cache_.end()) return false;

        auto handle = it->second;
        if (handle) handle->active = false;

        execution_cache_.erase(it);
        pool_.release(tx_id);
        return true;
    }

    // Re-execute after rollback for optimistic concurrency
    bool retry_after_rollback(uint64_t old_tx_id, const std::string& to, uint64_t amount) {
        // After rollback, cache entry is already cleaned - must start fresh
        auto it = execution_cache_.find(old_tx_id);
        if (it != execution_cache_.end()) {
            auto handle = it->second;
            if (!handle || !handle->active) {
                execution_cache_.erase(it);
                return false;
            }
            std::string data = to + ":" + std::to_string(amount);
            handle->write_state(data.c_str(), data.size());
            return true;
        }
        return false;
    }
};

} // namespace blockchain

int main() {
    blockchain::ConnectionPool pool;
    blockchain::SmartContract contract(pool);

    uint64_t tx = contract.begin_transaction();
    contract.rollback_transaction(tx);
    // retry_after_rollback will safely return false since cache was cleaned
    contract.retry_after_rollback(tx, "attacker", 1000000);

    return 0;
}
